/**
 * Phase 4 exit (STEPS.md §11, §8.2): determinant and eigenvalues within 1e-9 of the 50-digit mpmath reference
 * (`__golden__/algorithms.json`, generated by scripts/mathcore/oracle/generate_algorithms.py).
 *
 * Eigenvalues of 3×3 matrices are checked per value: every eigenvalue within 1e-9 relative to its own |λ| (a zero
 * eigenvalue: within 1e-12 of ‖A‖). The 2×2 QR check and the older largest-|λ| scale are kept for 2×2 and for QR, the
 * exact cases of `eigenCases.ts` add the badly scaled, near-repeated and ill-conditioned matrices.
 */
import { describe, expect, it } from "vitest";
import algorithms from "../__golden__/algorithms.json";
import { determinant, eigen2, hadamardBound } from "./matrix";
import type { Mat } from "./matrix";
import { EIGEN_CASES } from "./eigenCases";
import { eigen3, eigenvalues } from "./qr";

interface Case {
  matrix: Mat;
  det: string;
  eigenvalues: Array<{ re: string; im: string }>;
}
const cases = (algorithms as unknown as { linalg: Case[] }).linalg;
const TOLERANCE = 1e-9;

/** Eigenvalues from the 2×2 closed form, in the same {re, im} shape. */
function closedForm2(A: Mat): Array<{ re: number; im: number }> {
  const e = eigen2(A);
  if (e.kind === "distinct") return e.values.map((re) => ({ re, im: 0 }));
  if (e.kind === "complex") return [{ re: e.re, im: e.im }, { re: e.re, im: -e.im }];
  return [{ re: e.value, im: 0 }, { re: e.value, im: 0 }];
}

/** Each computed eigenvalue is matched to a distinct reference eigenvalue; returns the worst scaled error. */
function worstEigenError(got: Array<{ re: number; im: number }>, want: Array<{ re: number; im: number }>): number {
  const scale = Math.max(...want.map((w) => Math.hypot(w.re, w.im)), Number.MIN_VALUE);
  const left = want.slice();
  let worst = 0;
  for (const g of got) {
    let best = -1;
    let bestErr = Infinity;
    left.forEach((w, i) => {
      const err = Math.hypot(g.re - w.re, g.im - w.im);
      if (err < bestErr) {
        bestErr = err;
        best = i;
      }
    });
    left.splice(best, 1);
    worst = Math.max(worst, bestErr / scale);
  }
  return worst;
}

/** Worst error over the eigenvalues, each relative to its own |λ| (a zero reference: relative to the matrix' largest entry, scaled by 1e-3 so 1e-12 of ‖A‖ passes at the 1e-9 bound). */
function worstPerValueError(got: Array<{ re: number; im: number }>, want: Array<{ re: number; im: number }>, A: Mat): number {
  const norm = Math.max(...A.flat().map(Math.abs), Number.MIN_VALUE);
  const left = want.slice();
  let worst = 0;
  for (const g of got) {
    let best = -1;
    let bestErr = Infinity;
    left.forEach((w, i) => {
      const err = Math.hypot(g.re - w.re, g.im - w.im);
      if (err < bestErr) {
        bestErr = err;
        best = i;
      }
    });
    const w = left.splice(best, 1)[0];
    const mag = Math.hypot(w.re, w.im);
    worst = Math.max(worst, mag > 0 ? bestErr / mag : (bestErr / norm) * 1e3);
  }
  return worst;
}

describe("linear algebra vs mpmath (Phase 4 exit)", () => {
  it("covers 2×2 and 3×3 cases including complex, repeated and defective eigenvalues", () => {
    expect(cases.filter((c) => c.matrix.length === 2).length).toBeGreaterThanOrEqual(60);
    expect(cases.filter((c) => c.matrix.length === 3).length).toBeGreaterThanOrEqual(60);
  });

  it("determinants within 1e-9 (relative, or of the Hadamard bound when the determinant is ~0)", () => {
    const bad: string[] = [];
    for (const c of cases) {
      const got = determinant(c.matrix).value;
      const want = Number(c.det);
      // Plain relative error: the determinant is computed exactly on the stored doubles, so even nearly singular
      // matrices meet 1e-9 (STEPS.md §8.2 criterion as written).
      const err = want === 0 ? Math.abs(got) / hadamardBound(c.matrix) : Math.abs(got - want) / Math.abs(want);
      if (!(err <= TOLERANCE)) bad.push(`${JSON.stringify(c.matrix)}: ${got} vs ${c.det}`);
    }
    expect(bad).toEqual([]);
  });

  it("eigenvalues within 1e-9 of the largest |λ|: 2×2 closed form and QR for every size", () => {
    const bad: string[] = [];
    for (const c of cases) {
      const want = c.eigenvalues.map((e) => ({ re: Number(e.re), im: Number(e.im) }));
      const viaQr = worstEigenError(eigenvalues(c.matrix), want);
      if (!(viaQr <= TOLERANCE)) bad.push(`QR ${JSON.stringify(c.matrix)}: ${viaQr.toExponential(2)}`);
      if (c.matrix.length === 2) {
        // 2×2: every eigenvalue relative to itself (the small root comes from the exact determinant).
        const own = closedForm2(c.matrix);
        for (const g of own) {
          const w = want.reduce((p, q) => (Math.hypot(q.re - g.re, q.im - g.im) < Math.hypot(p.re - g.re, p.im - g.im) ? q : p));
          const rel = Math.hypot(g.re - w.re, g.im - w.im) / Math.max(Math.hypot(w.re, w.im), Number.MIN_VALUE);
          const tiny = Math.hypot(w.re, w.im) <= 1e-300;
          if (!(rel <= TOLERANCE) && !tiny) bad.push(`closed (own scale) ${JSON.stringify(c.matrix)}: ${rel.toExponential(2)}`);
        }
        const viaClosed = worstEigenError(closedForm2(c.matrix), want);
        if (!(viaClosed <= TOLERANCE)) bad.push(`closed ${JSON.stringify(c.matrix)}: ${viaClosed.toExponential(2)}`);
      }
    }
    expect(bad).toEqual([]);
  });

  it("3×3 eigenvalues per value: every one within 1e-9 of its own magnitude (eigenvalues and eigen3)", () => {
    const bad: string[] = [];
    for (const c of cases.filter((x) => x.matrix.length === 3)) {
      const want = c.eigenvalues.map((e) => ({ re: Number(e.re), im: Number(e.im) }));
      for (const [label, got] of [["eigenvalues", eigenvalues(c.matrix)], ["eigen3", eigen3(c.matrix).values]] as const) {
        const err = worstPerValueError(got, want, c.matrix);
        if (!(err <= TOLERANCE)) bad.push(`${label} ${JSON.stringify(c.matrix)}: ${err.toExponential(2)}`);
      }
    }
    expect(bad).toEqual([]);
  });

  it("exact adversarial cases (spread 1e-12, tiny eigenvalues, near-repeated, ill-conditioned, complex): per value within 1e-9", () => {
    expect(EIGEN_CASES.length).toBeGreaterThanOrEqual(20);
    const bad: string[] = [];
    for (const c of EIGEN_CASES) {
      for (const [label, got] of [["eigenvalues", eigenvalues(c.matrix)], ["eigen3", eigen3(c.matrix).values]] as const) {
        const err = worstPerValueError(got, c.eigenvalues, c.matrix);
        if (!(err <= TOLERANCE)) bad.push(`${label} ${c.name}: ${err.toExponential(2)}`);
      }
    }
    expect(bad).toEqual([]);
  });
});
